/**
 * Base64-embedded PNG of the Mouse mark: a hand-drawn white mouse with red
 * hearts, transparent background, 440x440 canvas (content trimmed tight to
 * 310x440, centered).
 *
 * Embedded as a module rather than read from disk at request time: the
 * opengraph-image route renders through Satori (next/og), which needs an
 * <img src> it can resolve without a network hop, and file tracing on Vercel
 * makes fs.readFileSync(process.cwd() + ...) fragile at request time. Since
 * this route is static, the string below is inlined at build time.
 */
export const MOUSE_LOGO_DATA_URL =
  "data:image/png;base64,";
